namespace ArmLro;

/// <summary>The ARM error contract: a code plus a human-readable message.</summary>
public sealed record ArmError(string? Code, string? Message);

/// <summary>Final outcome of a create-or-update operation once it reached a terminal state.</summary>
public sealed class ArmOperationResult
{
    /// <summary>True when the terminal status was Succeeded (case-insensitive).</summary>
    public required bool Succeeded { get; init; }

    /// <summary>The terminal status string exactly as the service reported it.</summary>
    public required string Status { get; init; }

    /// <summary>The final resource JSON on success; null on failure.</summary>
    public JsonElement? Resource { get; init; }

    /// <summary>The operation error (code/message) when the status was Failed or Canceled.</summary>
    public ArmError? Error { get; init; }
}

/// <summary>Polling knobs. All waiting goes through <see cref="Delay"/> — the library never sleeps.</summary>
public sealed class ArmLroClientOptions
{
    /// <summary>Maximum number of status-monitor polls before giving up with <see cref="ArmProtocolException"/>.</summary>
    public int MaxPolls { get; set; } = 60;

    /// <summary>Wait between polls when the response carries no Retry-After header.</summary>
    public TimeSpan DefaultPollDelay { get; set; } = TimeSpan.FromSeconds(30);

    /// <summary>How to wait. Defaults to <see cref="Task.Delay(TimeSpan, CancellationToken)"/>; tests inject a recorder.</summary>
    public Func<TimeSpan, CancellationToken, Task> Delay { get; set; } = Task.Delay;
}
