namespace ArmLro;

/// <summary>
/// Acquires app-only tokens via the Microsoft identity platform OAuth 2.0 client-credentials
/// flow (POST {tenant}/oauth2/v2.0/token, application/x-www-form-urlencoded) and caches the
/// result until expires_in elapses, measured against the injected clock.
/// </summary>
public sealed class EntraTokenProvider
{
    private readonly HttpClient _http;
    private readonly Uri _tokenEndpoint;
    private readonly string _clientId;
    private readonly string _clientSecret;
    private readonly string _scope;
    private readonly Func<DateTimeOffset> _now;
    private readonly SemaphoreSlim _gate = new(1, 1);

    private string? _cachedToken;
    private DateTimeOffset _expiresAt;

    public EntraTokenProvider(
        HttpClient http,
        Uri tokenEndpoint,
        string clientId,
        string clientSecret,
        string scope,
        Func<DateTimeOffset> now)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        _tokenEndpoint = tokenEndpoint ?? throw new ArgumentNullException(nameof(tokenEndpoint));
        _clientId = clientId ?? throw new ArgumentNullException(nameof(clientId));
        _clientSecret = clientSecret ?? throw new ArgumentNullException(nameof(clientSecret));
        _scope = scope ?? throw new ArgumentNullException(nameof(scope));
        _now = now ?? throw new ArgumentNullException(nameof(now));
    }

    public async Task<string> GetTokenAsync(CancellationToken cancellationToken = default)
    {
        await _gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            if (_cachedToken is not null && _now() < _expiresAt)
            {
                return _cachedToken;
            }

            using var content = new FormUrlEncodedContent(new Dictionary<string, string>
            {
                ["grant_type"] = "client_credentials",
                ["client_id"] = _clientId,
                ["client_secret"] = _clientSecret,
                ["scope"] = _scope,
            });
            using var request = new HttpRequestMessage(HttpMethod.Post, _tokenEndpoint) { Content = content };
            using var response = await _http.SendAsync(request, cancellationToken).ConfigureAwait(false);
            var body = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);

            if (!response.IsSuccessStatusCode)
            {
                // Only the OAuth error code goes into the message: error_description is
                // server-supplied text and must never travel next to the client secret.
                var errorCode = TryReadStringProperty(body, "error");
                throw new ArmAuthException(
                    $"Token request failed with status {(int)response.StatusCode}" +
                    (errorCode is null ? "." : $": {errorCode}."))
                {
                    OAuthErrorCode = errorCode,
                };
            }

            using var doc = JsonDocument.Parse(body);
            if (!doc.RootElement.TryGetProperty("access_token", out var accessToken) ||
                accessToken.ValueKind != JsonValueKind.String)
            {
                throw new ArmAuthException("Token response did not contain an access_token.");
            }
            var expiresInSeconds = doc.RootElement.TryGetProperty("expires_in", out var expiresIn)
                ? ReadSeconds(expiresIn)
                : 0;

            _cachedToken = accessToken.GetString()!;
            _expiresAt = _now().AddSeconds(expiresInSeconds);
            return _cachedToken;
        }
        finally
        {
            _gate.Release();
        }
    }

    private static long ReadSeconds(JsonElement element) => element.ValueKind switch
    {
        JsonValueKind.Number => element.GetInt64(),
        // Some STS responses historically carried expires_in as a JSON string.
        JsonValueKind.String when long.TryParse(element.GetString(), out var parsed) => parsed,
        _ => 0,
    };

    private static string? TryReadStringProperty(string json, string name)
    {
        try
        {
            using var doc = JsonDocument.Parse(json);
            return doc.RootElement.ValueKind == JsonValueKind.Object &&
                   doc.RootElement.TryGetProperty(name, out var value) &&
                   value.ValueKind == JsonValueKind.String
                ? value.GetString()
                : null;
        }
        catch (JsonException)
        {
            return null;
        }
    }
}
"}

