using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;

namespace ArmLro;

/// <summary>
/// Submits an ARM create-or-update (PUT) and drives the documented asynchronous-operation
/// protocol to a terminal answer: Azure-AsyncOperation over Operation-Location over Location
/// for the status monitor, Retry-After between polls, Succeeded/Failed/Canceled as the
/// terminal states, and a final GET of the resource when an operation-status monitor succeeds.
/// </summary>
public sealed class ArmLroClient
{
    private static readonly string[] TerminalStates = { "Succeeded", "Failed", "Canceled" };

    private readonly HttpClient _http;
    private readonly EntraTokenProvider _tokens;
    private readonly ArmLroClientOptions _options;

    public ArmLroClient(HttpClient http, EntraTokenProvider tokens, ArmLroClientOptions options)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        _tokens = tokens ?? throw new ArgumentNullException(nameof(tokens));
        _options = options ?? throw new ArgumentNullException(nameof(options));
        if (_http.BaseAddress is null)
        {
            throw new ArgumentException("HttpClient must have a base address (the ARM endpoint).", nameof(http));
        }
    }

    public async Task<ArmOperationResult> CreateOrUpdateAsync(
        string resourcePath,
        string apiVersion,
        string requestBodyJson,
        CancellationToken cancellationToken = default)
    {
        var resourceUri = new Uri(_http.BaseAddress!, $"{resourcePath}?api-version={Uri.EscapeDataString(apiVersion)}");

        using var put = new HttpRequestMessage(HttpMethod.Put, resourceUri)
        {
            Content = new StringContent(requestBodyJson, Encoding.UTF8, "application/json"),
        };
        using var response = await SendAsync(put, cancellationToken).ConfigureAwait(false);
        var body = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);

        if (!response.IsSuccessStatusCode)
        {
            throw RequestError(response.StatusCode, body);
        }

        var monitor = SelectMonitor(response);
        if (monitor is null)
        {
            if (response.StatusCode == HttpStatusCode.Accepted)
            {
                throw new ArmProtocolException(
                    "202 Accepted response carried no Azure-AsyncOperation, Operation-Location, or Location header to monitor.");
            }
            return CompletedResource(body);
        }

        var initialDelay = RetryAfter(response) ?? _options.DefaultPollDelay;
        return await PollAsync(monitor.Value, initialDelay, resourceUri, cancellationToken).ConfigureAwait(false);
    }

    private enum MonitorKind
    {
        /// <summary>Azure-AsyncOperation / Operation-Location: 200 with a status document, never the resource.</summary>
        OperationStatus,

        /// <summary>Location: 202 while running, 200 with the final resource body when done.</summary>
        Location,
    }

    private (Uri Url, MonitorKind Kind)? SelectMonitor(HttpResponseMessage response)
    {
        foreach (var (header, kind) in new[]
        {
            ("Azure-AsyncOperation", MonitorKind.OperationStatus),
            ("Operation-Location", MonitorKind.OperationStatus),
            ("Location", MonitorKind.Location),
        })
        {
            if (response.Headers.TryGetValues(header, out var values) &&
                values.FirstOrDefault() is { Length: > 0 } value)
            {
                if (!Uri.TryCreate(value, UriKind.Absolute, out var url))
                {
                    throw new ArmProtocolException($"{header} header value '{value}' is not an absolute URL.");
                }
                if (!string.Equals(url.Host, _http.BaseAddress!.Host, StringComparison.OrdinalIgnoreCase))
                {
                    throw new ArmProtocolException(
                        $"{header} status monitor '{url}' points at untrusted host '{url.Host}' instead of " +
                        $"'{_http.BaseAddress.Host}'; refusing to poll it or send credentials there.");
                }
                return (url, kind);
            }
        }
        return null;
    }

    private async Task<ArmOperationResult> PollAsync(
        (Uri Url, MonitorKind Kind) monitor,
        TimeSpan delay,
        Uri resourceUri,
        CancellationToken cancellationToken)
    {
        for (var poll = 0; poll < _options.MaxPolls; poll++)
        {
            await _options.Delay(delay, cancellationToken).ConfigureAwait(false);

            using var request = new HttpRequestMessage(HttpMethod.Get, monitor.Url);
            using var response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
            var body = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);

            if (monitor.Kind == MonitorKind.Location && response.StatusCode == HttpStatusCode.Accepted)
            {
                delay = RetryAfter(response) ?? _options.DefaultPollDelay;
                continue;
            }
            if (!response.IsSuccessStatusCode)
            {
                throw RequestError(response.StatusCode, body);
            }
            if (monitor.Kind == MonitorKind.Location)
            {
                // The 200 body from a Location monitor is the final resource itself.
                return CompletedResource(body);
            }

            var status = ReadMonitorStatus(body, out var error);
            if (status.Equals("Succeeded", StringComparison.OrdinalIgnoreCase))
            {
                return new ArmOperationResult
                {
                    Succeeded = true,
                    Status = status,
                    Resource = await FetchResourceAsync(resourceUri, cancellationToken).ConfigureAwait(false),
                };
            }
            if (status.Equals("Failed", StringComparison.OrdinalIgnoreCase) ||
                status.Equals("Canceled", StringComparison.OrdinalIgnoreCase))
            {
                return new ArmOperationResult { Succeeded = false, Status = status, Error = error };
            }

            delay = RetryAfter(response) ?? _options.DefaultPollDelay;
        }

        throw new ArmProtocolException(
            $"Operation did not reach a terminal state ({string.Join("/", TerminalStates)}) within {_options.MaxPolls} polls.");
    }

    private async Task<JsonElement?> FetchResourceAsync(Uri resourceUri, CancellationToken cancellationToken)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, resourceUri);
        using var response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
        var body = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);
        if (!response.IsSuccessStatusCode)
        {
            throw RequestError(response.StatusCode, body);
        }
        return ParseJson(body);
    }

    private async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        var token = await _tokens.GetTokenAsync(cancellationToken).ConfigureAwait(false);
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
        return await _http.SendAsync(request, cancellationToken).ConfigureAwait(false);
    }

    private static ArmOperationResult CompletedResource(string body)
    {
        var resource = ParseJson(body);
        var status = resource is { ValueKind: JsonValueKind.Object } element &&
                     element.TryGetProperty("properties", out var properties) &&
                     properties.ValueKind == JsonValueKind.Object &&
                     properties.TryGetProperty("provisioningState", out var state) &&
                     state.ValueKind == JsonValueKind.String
            ? state.GetString()!
            : "Succeeded";
        var succeeded = !status.Equals("Failed", StringComparison.OrdinalIgnoreCase) &&
                        !status.Equals("Canceled", StringComparison.OrdinalIgnoreCase);
        return new ArmOperationResult
        {
            Succeeded = succeeded,
            Status = status,
            Resource = succeeded ? resource : null,
        };
    }

    private static string ReadMonitorStatus(string body, out ArmError? error)
    {
        error = null;
        JsonElement? root = ParseJson(body);
        if (root is not { ValueKind: JsonValueKind.Object } element ||
            !element.TryGetProperty("status", out var status) ||
            status.ValueKind != JsonValueKind.String)
        {
            throw new ArmProtocolException(
                "Status monitor response did not include the required 'status' property.");
        }
        if (element.TryGetProperty("error", out var errorElement))
        {
            error = ReadError(errorElement);
        }
        return status.GetString()!;
    }

    private static ArmRequestException RequestError(HttpStatusCode statusCode, string body)
    {
        ArmError? error = null;
        try
        {
            using var doc = JsonDocument.Parse(body);
            if (doc.RootElement.ValueKind == JsonValueKind.Object &&
                doc.RootElement.TryGetProperty("error", out var errorElement))
            {
                error = ReadError(errorElement);
            }
        }
        catch (JsonException)
        {
        }
        var detail = error is null ? "" : $": {error.Code}: {error.Message}";
        return new ArmRequestException($"ARM request failed with status {(int)statusCode}{detail}", statusCode, error);
    }

    private static ArmError? ReadError(JsonElement element)
    {
        if (element.ValueKind != JsonValueKind.Object)
        {
            return null;
        }
        string? Read(string name) =>
            element.TryGetProperty(name, out var value) && value.ValueKind == JsonValueKind.String
                ? value.GetString()
                : null;
        return new ArmError(Read("code"), Read("message"));
    }

    private static TimeSpan? RetryAfter(HttpResponseMessage response)
        => response.Headers.RetryAfter?.Delta;

    private static JsonElement? ParseJson(string body)
    {
        if (string.IsNullOrWhiteSpace(body))
        {
            return null;
        }
        try
        {
            using var doc = JsonDocument.Parse(body);
            return doc.RootElement.Clone();
        }
        catch (JsonException ex)
        {
            throw new ArmProtocolException($"Response body was not valid JSON: {ex.Message}");
        }
    }
}
"}
